function get(row, keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') {
      return row[key];
    }
  }
  return '';
}

function normalizeWhatsApp(input) {
  if (!input) return '';

  let v = String(input).replace(/[^0-9+]/g, '');

  if (v.startsWith('+')) return v;
  if (v.length === 10) return '+91' + v;
  if (v.startsWith('91') && v.length === 12) return '+' + v;

  return v;
}

const output = [];

for (const item of $input.all()) {
  const row = item.json;

  const status = String(get(row, ['status', 'Status'])).toLowerCase().trim();
  const processed = String(get(row, ['processed', 'Processed'])).toLowerCase().trim();

  const alreadyDone =
    processed === 'true' ||
    processed === 'yes' ||
    [
      'scored',
      'interview scheduled',
      'manual review',
      'rejection pending hr approval',
      'rejected',
      'hired',
      'on hold'
    ].includes(status);

  if (alreadyDone) continue;

  const fullName = get(row, ['full_name', 'Full Name']);
  const email = get(row, ['email', 'Email Address', 'Email']);
  const rawWhatsapp = get(row, [
    'whatsapp_number',
    'WhatsApp Number',
    'phone',
    'Phone Number'
  ]);

  const resumeLink = get(row, [
    'resume_link',
    'Resume Google Drive PDF Link'
  ]);

  const whatsapp = normalizeWhatsApp(rawWhatsapp);

  if (!fullName || !email || !whatsapp || !resumeLink) {
    continue;
  }

  output.push({
    json: {
      timestamp: get(row, ['timestamp', 'Timestamp']),
      full_name: fullName,
      email,
      whatsapp_number: whatsapp,
      phone: get(row, ['phone', 'Phone Number']),
      city_state: get(row, ['city_state', 'City / State']),
      linkedin_url: get(row, ['linkedin_url', 'LinkedIn Profile URL']),
      portfolio_url: get(row, ['portfolio_url', 'Portfolio / Demo URL']),
      github_url: get(row, ['github_url', 'GitHub URL']),
      resume_link: resumeLink,
      job_role: get(row, ['job_role', 'Role Applying For']) || 'AI Automation Engineer',
      experience_years: get(row, ['experience_years', 'Years of Experience']),
      notice_period: get(row, ['notice_period', 'Notice Period']),
      expected_salary_or_charges: get(row, [
        'expected_salary_or_charges',
        'Expected Salary / Project Charges'
      ]),
      employment_type: get(row, ['employment_type', 'Employment Type']),
      skills_checklist: get(row, ['skills_checklist', 'Skills Checklist']),
      has_n8n_production: get(row, [
        'has_n8n_production',
        'Have you built n8n workflows in production?'
      ]),
      has_local_llm_rag: get(row, [
        'has_local_llm_rag',
        'Have you deployed local LLM or RAG system?'
      ]),
      automation_built_end_to_end: get(row, [
        'automation_built_end_to_end',
        'Describe one automation you built end to end'
      ]),
      automation_outcome: get(row, [
        'automation_outcome',
        'What business outcome did it create?'
      ]),
      client_industries: get(row, [
        'client_industries',
        'Industries you have automated'
      ]),
      comfortable_presenting_to_founder_md: get(row, [
        'comfortable_presenting_to_founder_md',
        'Can you present automation outcomes to a founder / MD?'
      ]),
      whatsapp_opt_in: get(row, [
        'whatsapp_opt_in',
        'I agree to receive updates on WhatsApp'
      ]),
      source_post: get(row, ['source_post', 'Source Post']),
      status: 'New',
      processed: false
    }
  });
}

return output;

let base = {};

try {
  base = $('Resume Loop').item.json;
} catch (error) {
  base = {};
}

const resumeText =
  $json.text ||
  $json.data ||
  $json.content ||
  $json.extractedText ||
  Object.values($json).join('\n');

const hiringContext = `
Hiring context:
The roles are AI Automation Engineer / n8n Automation Developer / AI Automation Expert / Automation Workflow Lead.

Important skills:
- n8n production workflows, Make, Zapier
- AI agents, email classification, reply drafting, sales pipeline automation
- Private RAG knowledge vault, vector DBs, Ollama / LM Studio
- Python or Node.js, JavaScript, REST APIs, webhooks, OAuth, JSON
- Gmail API / Microsoft Graph
- CRM systems: Bitrix24, Zoho, HubSpot or similar
- Finance workflows: invoicing, reminders, reporting
- Marketing outreach sequences and campaign tracking
- WhatsApp automation and CRM lead management
- Docker, deployment, local infrastructure
- Ability to present outcomes to founder / MD
`;

const prompt = `
You are an expert technical recruiter for AI automation roles.

${hiringContext}

Candidate form details:
Name: ${base.full_name}
Email: ${base.email}
WhatsApp: ${base.whatsapp_number}
Role applying for: ${base.job_role}
Experience years: ${base.experience_years}
Notice period: ${base.notice_period}
Expected salary or charges: ${base.expected_salary_or_charges}
Employment type: ${base.employment_type}
Skills checklist: ${base.skills_checklist}
n8n production experience: ${base.has_n8n_production}
Local LLM / RAG experience: ${base.has_local_llm_rag}
End-to-end automation built: ${base.automation_built_end_to_end}
Business outcome: ${base.automation_outcome}
Portfolio: ${base.portfolio_url}
GitHub: ${base.github_url}
LinkedIn: ${base.linkedin_url}

Resume text:
${resumeText}

Score the candidate from 0 to 100 using this weighting:
1. n8n / workflow automation production experience: 20
2. AI agents + LLM automation: 15
3. RAG + local LLM infrastructure: 15
4. APIs, webhooks, OAuth, Gmail/MS Graph: 15
5. CRM + sales/marketing/finance automation: 15
6. Python/Node.js + Docker/deployment: 10
7. Communication and founder-facing business outcome clarity: 10

Return only valid JSON. No markdown. No text outside JSON.

Required JSON format:
{
  "score": 90,
  "category": "Strong",
  "summary": "Short candidate summary",
  "strengths": ["strength 1", "strength 2"],
  "weaknesses": ["weakness 1", "weakness 2"],
  "recommended_action": "Interview",
  "risk_flags": ["risk 1", "risk 2"],
  "interview_questions": ["question 1", "question 2"]
}

Rules:
- Strong = score 75 or above
- Average = score 50 to 74
- Weak = below 50
- recommended_action must be Interview, Manual Review, or HR Approval Before Rejection
- Do not judge age, gender, religion, caste, location, photo, or personal background.
- Judge only skills, experience, projects, communication, and role fit.
`;

return {
  json: {
    ...base,
    resume_text: resumeText,
    ai_prompt: prompt
  }
};

const base = $('Build AI Hiring Score Prompt').item.json;

function parseAiOutput(input) {
  if (!input) return {};

  if (typeof input === 'object') return input;

  if (typeof input === 'string') {
    let text = input.trim();

    text = text.replace(/^```json/i, '');
    text = text.replace(/^```/i, '');
    text = text.replace(/```$/i, '');
    text = text.trim();

    try {
      return JSON.parse(text);
    } catch (error) {
      return {};
    }
  }

  return {};
}

let raw =
  $json.response?.output ||
  $json.output ||
  $json.text ||
  $json;

const parsed = parseAiOutput(raw);

const score = Number(parsed.score || 0);

let category = parsed.category;

if (!['Strong', 'Average', 'Weak'].includes(category)) {
  category = score >= 75 ? 'Strong' : score >= 50 ? 'Average' : 'Weak';
}

let recommendedAction = parsed.recommended_action;

if (!['Interview', 'Manual Review', 'HR Approval Before Rejection'].includes(recommendedAction)) {
  recommendedAction =
    category === 'Strong'
      ? 'Interview'
      : category === 'Average'
      ? 'Manual Review'
      : 'HR Approval Before Rejection';
}

return {
  json: {
    ...base,

    ai_score: score,
    ai_category: category,
    ai_summary: parsed.summary || '',

    strengths: Array.isArray(parsed.strengths)
      ? parsed.strengths.join(', ')
      : parsed.strengths || '',

    weaknesses: Array.isArray(parsed.weaknesses)
      ? parsed.weaknesses.join(', ')
      : parsed.weaknesses || '',

    recommended_action: recommendedAction,

    risk_flags: Array.isArray(parsed.risk_flags)
      ? parsed.risk_flags.join(', ')
      : parsed.risk_flags || '',

    interview_questions: Array.isArray(parsed.interview_questions)
      ? parsed.interview_questions.join(' | ')
      : parsed.interview_questions || '',

    status: 'Scored',
    processed: true,
    updated_at: new Date().toISOString()
  }
};

