function getTomorrow11AMIST() {
  const now = new Date();

  const istNow = new Date(now.getTime() + 5.5 * 60 * 60 * 1000);

  const year = istNow.getUTCFullYear();
  const month = istNow.getUTCMonth();
  const day = istNow.getUTCDate() + 1;

  // 11:00 AM IST = 05:30 AM UTC
  const startUtc = new Date(Date.UTC(year, month, day, 5, 30, 0));
  const endUtc = new Date(startUtc.getTime() + 30 * 60 * 1000);

  return {
    start: startUtc.toISOString(),
    end: endUtc.toISOString()
  };
}

const row = $json;

const score = Number(row.ai_score || 0);
const category = String(row.ai_category || '').trim();
const recommendedAction = String(row.recommended_action || '').trim();

let route = 'manual_review';

if (recommendedAction === 'Interview' || category === 'Strong' || score >= 75) {
  route = 'interview';
} else if (recommendedAction === 'Manual Review' || category === 'Average' || score >= 50) {
  route = 'manual_review';
} else {
  route = 'hr_rejection_approval';
}

const interview = getTomorrow11AMIST();

return {
  json: {
    ...row,
    route,
    whatsapp_number: normalizeWhatsApp(row.whatsapp_number || row.phone),
    interview_start: interview.start,
    interview_end: interview.end,
    interview_time: interview.start,
    updated_at: new Date().toISOString()
  }
};

