const candidate = $('Decide Interview / Manual / HR Approval').item.json;
const event = $json;

let meetLink = event.hangoutLink || '';

if (!meetLink && event.conferenceData && Array.isArray(event.conferenceData.entryPoints)) {
  const videoEntry = event.conferenceData.entryPoints.find(
    entry => entry.entryPointType === 'video'
  );

  if (videoEntry && videoEntry.uri) {
    meetLink = videoEntry.uri;
  }
}

const calendarEventLink = event.htmlLink || '';
const calendarEventId = event.id || '';

return {
  json: {
    ...candidate,
